import{_ as h,o as t,c,a2 as g}from"./chunks/framework.CqpfiAoK.js";const d=JSON.parse('{"title":"Phân loại và Cộng sinh của các Chủng tộc Khác","description":"","frontmatter":{},"headers":[],"relativePath":"vi/0052-异族分类与共生.md","filePath":"vi/0052-异族分类与共生.md"}'),i={name:"vi/0052-异族分类与共生.md"};function a(o,n,l,r,u,s){return t(),c("div",null,[...n[0]||(n[0]=[g('<h1 id="phan-loai-va-cong-sinh-cua-cac-chung-toc-khac" tabindex="-1">Phân loại và Cộng sinh của các Chủng tộc Khác <a class="header-anchor" href="#phan-loai-va-cong-sinh-cua-cac-chung-toc-khac" aria-label="Permalink to &quot;Phân loại và Cộng sinh của các Chủng tộc Khác&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Mục</th><th>Nội dung</th></tr></thead><tbody><tr><td>Số tài liệu</td><td>52</td></tr><tr><td>Mô-đun</td><td>Chủng tộc và Hình thái sự sống</td></tr><tr><td>Từ khóa cốt lõi</td><td>Chủng tộc khác, tiêu chuẩn phân loại, chế độ cộng sinh, tôn trọng văn hóa, thích ứng chủng tộc</td></tr></tbody></table><h2 id="_1-đinh-nghia-khai-niem-chung-toc-khac" tabindex="-1">1. Định nghĩa khái niệm Chủng tộc Khác <a class="header-anchor" href="#_1-đinh-nghia-khai-niem-chung-toc-khac" aria-label="Permalink to &quot;1. Định nghĩa khái niệm Chủng tộc Khác&quot;">​</a></h2><p>Trong bối cảnh Nền văn minh Cộng sinh Mỏ neo, &quot;chủng tộc khác&quot; là một khái niệm tương đối so với Chủng tộc Người, đề cập đến tất cả các chủng tộc ngoài Chủng tộc Người. Cần đặc biệt nhấn mạnh rằng khái niệm &quot;chủng tộc khác&quot; chỉ có ý nghĩa phân loại học, và không mang bất kỳ đánh giá giá trị hay ý nghĩa phân biệt đối xử nào. Trong khuôn khổ Hiến pháp Cộng sinh, chủng tộc khác và Chủng tộc Người hưởng thụ địa vị pháp luật và quyền cơ bản hoàn toàn bình đẳng.</p><p>Mục đích của việc giới thiệu khái niệm chủng tộc khác là để hệ thống hóa việc nhận thức và nghiên cứu các hình thái sự sống khác ngoài Chủng tộc Người, cung cấp cơ sở khoa học cho việc xây dựng chính sách cộng sinh có mục tiêu, các biện pháp bảo vệ văn hóa và kế hoạch thích ứng chủng tộc, chứ không phải để coi chủng tộc khác là &quot;kẻ khác&quot; hay &quot;kẻ lạ&quot;.</p><h2 id="_2-tieu-chuan-phan-loai-chung-toc-khac" tabindex="-1">2. Tiêu chuẩn phân loại Chủng tộc Khác <a class="header-anchor" href="#_2-tieu-chuan-phan-loai-chung-toc-khac" aria-label="Permalink to &quot;2. Tiêu chuẩn phân loại Chủng tộc Khác&quot;">​</a></h2><p>Các chủng tộc khác ở Hengyuanzhou được phân loại theo nhiều chiều, tạo thành hệ thống phân loại đa chiều:</p><h3 id="_1-theo-dong-doi-su-song" tabindex="-1">(1) Theo dòng dõi sự sống <a class="header-anchor" href="#_1-theo-dong-doi-su-song" aria-label="Permalink to &quot;(1) Theo dòng dõi sự sống&quot;">​</a></h3><p>Đây là tiêu chuẩn phân loại cơ bản nhất, xem chi tiết 《50-Tổng quan về phả hệ tất cả các chủng tộc》:</p><table tabindex="0"><thead><tr><th>Dòng dõi</th><th>Các chủng tộc khác bao gồm</th></tr></thead><tbody><tr><td>Chủng tộc vật chất gốc carbon</td><td>Chủng tộc Thú, Chủng tộc Vảy, Chủng tộc Lông vũ, Chủng tộc Cây, v.v.</td></tr><tr><td>Chủng tộc ngưng tụ năng lượng</td><td>Chủng tộc Linh, Chủng tộc Hỏa, Chủng tộc Thủy, Chủng tộc Phong, Chủng tộc Sấm, v.v.</td></tr><tr><td>Chủng tộc cấu tạo cơ khí</td><td>Chủng tộc Cơ, Chủng tộc Số, Chủng tộc Tinh thể, v.v.</td></tr><tr><td>Chủng tộc thông tin ý thức</td><td>Chủng tộc Mộng, Chủng tộc Ảnh, Chủng tộc Niệm, Chủng tộc Hồn, v.v.</td></tr><tr><td>Chủng tộc đột biến hỗn hợp</td><td>Chủng tộc Bán thú, Chủng tộc Yêu linh, Chủng tộc Nhân cơ, Thể hồn kép, v.v.</td></tr></tbody></table><h3 id="_2-theo-muc-đo-van-minh" tabindex="-1">(2) Theo mức độ văn minh <a class="header-anchor" href="#_2-theo-muc-đo-van-minh" aria-label="Permalink to &quot;(2) Theo mức độ văn minh&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Cấp độ</th><th>Tên</th><th>Đặc điểm</th><th>Chủng tộc đại diện</th></tr></thead><tbody><tr><td>Cấp độ thứ nhất</td><td>Chủng tộc văn minh nguyên thủy</td><td>Chưa thiết lập hệ thống xã hội ổn định, tồn tại dưới dạng bộ lạc</td><td>Một số nhánh của Chủng tộc Thú, Chủng tộc Cây nguyên thủy</td></tr><tr><td>Cấp độ thứ hai</td><td>Chủng tộc văn minh cổ điển</td><td>Đã thiết lập hệ thống nhà nước và văn hóa cổ điển, đang ở giai đoạn nông nghiệp hoặc thủ công nghiệp</td><td>Một số Chủng tộc Vảy, Chủng tộc Lông vũ</td></tr><tr><td>Cấp độ thứ ba</td><td>Chủng tộc văn minh công nghệ</td><td>Đã phát triển văn minh công nghệ, bước vào thời đại công nghiệp hoặc thông tin</td><td>Chủng tộc Cơ, Chủng tộc Số, một số Chủng tộc Người</td></tr><tr><td>Cấp độ thứ tư</td><td>Chủng tộc văn minh tu luyện</td><td>Sử dụng hệ thống tu luyện làm hình thái văn minh cốt lõi, người tu luyện chiếm ưu thế trong xã hội</td><td>Chủng tộc Linh, Chủng tộc Long, một số Chủng tộc Người</td></tr><tr><td>Cấp độ thứ năm</td><td>Chủng tộc văn minh cộng sinh</td><td>Đã gia nhập Nền văn minh Cộng sinh Mỏ neo, chấp nhận lý tưởng và thể chế cộng sinh</td><td>Tất cả các chủng tộc đã gia nhập văn minh cộng sinh</td></tr></tbody></table><h3 id="_3-theo-su-thich-ung-voi-moi-truong" tabindex="-1">(3) Theo sự thích ứng với môi trường <a class="header-anchor" href="#_3-theo-su-thich-ung-voi-moi-truong" aria-label="Permalink to &quot;(3) Theo sự thích ứng với môi trường&quot;">​</a></h3><ul><li><strong>Chủng tộc trên cạn</strong>: Chủng tộc thích ứng với môi trường trên cạn, như Chủng tộc Người, Chủng tộc Thú, Chủng tộc Cơ khí.</li><li><strong>Chủng tộc dưới nước</strong>: Chủng tộc thích ứng với môi trường thủy vực, như Chủng tộc Vảy, Chủng tộc Thủy, một số chủng tộc hỗn hợp.</li><li><strong>Chủng tộc trên không</strong>: Chủng tộc thích ứng với môi trường cao không hoặc bay lượn, như Chủng tộc Lông vũ, Chủng tộc Phong.</li><li><strong>Chủng tộc lửa</strong>: Chủng tộc thích ứng với môi trường nhiệt độ cao, như Chủng tộc Hỏa, một số Chủng tộc Vảy.</li><li><strong>Chủng tộc băng</strong>: Chủng tộc thích ứng với môi trường nhiệt độ thấp, như Chủng tộc Băng, một số Chủng tộc Cây.</li><li><strong>Chủng tộc năng lượng</strong>: Chủng tộc thích ứng với môi trường năng lượng nồng độ cao, như Chủng tộc Linh, Chủng tộc Sấm.</li><li><strong>Chủng tộc không gian</strong>: Chủng tộc thích ứng với môi trường khe nứt không gian hoặc không gian lạ, như Chủng tộc Ảnh, một số Chủng tộc Niệm.</li></ul><h3 id="_4-theo-hinh-thai-xa-hoi" tabindex="-1">(4) Theo hình thái xã hội <a class="header-anchor" href="#_4-theo-hinh-thai-xa-hoi" aria-label="Permalink to &quot;(4) Theo hình thái xã hội&quot;">​</a></h3><ul><li><strong>Chủng tộc cá nhân chủ nghĩa</strong>: Nhấn mạnh sự độc lập và tự do cá nhân, cấu trúc xã hội lỏng lẻo, như một số Chủng tộc Linh, Chủng tộc Ảnh.</li><li><strong>Chủng tộc tập thể chủ nghĩa</strong>: Nhấn mạnh lợi ích và hợp tác tập thể, cấu trúc xã hội chặt chẽ, như Chủng tộc Kiến, Chủng tộc Ong, một số Chủng tộc Cơ khí.</li><li><strong>Chủng tộc gia đình chủ nghĩa</strong>: Sử dụng gia đình huyết thống làm đơn vị xã hội cơ bản, như Chủng tộc Long, một số Chủng tộc Thú.</li><li><strong>Chủng tộc tôn giáo chủ nghĩa</strong>: Sử dụng niềm tin tôn giáo làm cốt lõi gắn kết xã hội, như một số chủng tộc tế lễ.</li><li><strong>Chủng tộc kỹ thuật chủ nghĩa</strong>: Sử dụng phát triển công nghệ làm mục tiêu xã hội cốt lõi, như Chủng tộc Cơ khí, Chủng tộc Số.</li></ul><h2 id="_3-cac-che-đo-cong-sinh-chinh-cua-chung-toc-khac" tabindex="-1">3. Các chế độ cộng sinh chính của Chủng tộc Khác <a class="header-anchor" href="#_3-cac-che-đo-cong-sinh-chinh-cua-chung-toc-khac" aria-label="Permalink to &quot;3. Các chế độ cộng sinh chính của Chủng tộc Khác&quot;">​</a></h2><p>Đối với các loại chủng tộc khác nhau, Nền văn minh Cộng sinh Mỏ neo áp dụng các chế độ cộng sinh khác biệt:</p><h3 id="_1-che-đo-cong-sinh-cua-chung-toc-vat-chat-goc-carbon" tabindex="-1">(1) Chế độ cộng sinh của Chủng tộc vật chất gốc carbon <a class="header-anchor" href="#_1-che-đo-cong-sinh-cua-chung-toc-vat-chat-goc-carbon" aria-label="Permalink to &quot;(1) Chế độ cộng sinh của Chủng tộc vật chất gốc carbon&quot;">​</a></h3><ul><li><strong>Chủng tộc Thú</strong>: Phát huy ưu thế về năng lực thể chất và giác quan của Chủng tộc Thú, đảm nhận vai trò quan trọng trong các lĩnh vực như thăm dò tài nguyên, an ninh và phòng thủ, giám sát môi trường. Đồng thời bảo vệ văn hóa bộ lạc và truyền thống hoang dã của Chủng tộc Thú, cấm việc thuần hóa cưỡng bức.</li><li><strong>Chủng tộc Vảy</strong>: Phát huy khả năng thích ứng thủy vực của Chủng tộc Vảy, đảm nhận vai trò trong các lĩnh vực như phát triển tài nguyên thủy vực, xây dựng dưới nước, bảo vệ hệ sinh thái thủy vực. Chủng tộc Long, với tư cách là nhánh mạnh mẽ của Chủng tộc Vảy, đóng vai trò quan trọng trong tu luyện cấp cao và bảo vệ văn minh.</li><li><strong>Chủng tộc Lông vũ</strong>: Phát huy khả năng bay lượn của Chủng tộc Lông vũ, đảm nhận vai trò trong các lĩnh vực như giao thông không khí, giám sát thời tiết, tuần tra không phận. Bảo vệ môi trường sống cao không và lộ trình di cư của Chủng tộc Lông vũ.</li><li><strong>Chủng tộc Cây</strong>: Phát huy khả năng cộng sinh tự nhiên của Chủng tộc Cây, đảm nhận vai trò trong các lĩnh vực như bảo vệ sinh thái, quản lý môi trường, phát triển tài nguyên thực vật, chữa lành y tế. Tuổi thọ dài của Chủng tộc Cây làm cho nó trở thành một lực lượng quan trọng cho việc kế thừa lịch sử và lập kế hoạch dài hạn.</li></ul><h3 id="_2-che-đo-cong-sinh-cua-chung-toc-ngung-tu-nang-luong" tabindex="-1">(2) Chế độ cộng sinh của Chủng tộc ngưng tụ năng lượng <a class="header-anchor" href="#_2-che-đo-cong-sinh-cua-chung-toc-ngung-tu-nang-luong" aria-label="Permalink to &quot;(2) Chế độ cộng sinh của Chủng tộc ngưng tụ năng lượng&quot;">​</a></h3><ul><li><strong>Chủng tộc Linh</strong>: Phát huy khả năng điều khiển năng lượng và thiên tài tu luyện của Chủng tộc Linh, đảm nhận vai trò cốt lõi trong các lĩnh vực như nghiên cứu hệ thống tu luyện, điều tiết năng lượng, hướng dẫn tu luyện cấp cao. Chủng tộc Linh là nhà nghiên cứu và người kế thừa quan trọng của ba trăm hệ thống tu luyện nguyên bản.</li><li><strong>Chủng tộc Nguyên tố (Hỏa/Thủy/Phong/Sấm)</strong>: Phát huy khả năng điều khiển nguyên tố của mỗi chủng tộc, đảm nhận vai trò trong các lĩnh vực như phát triển năng lượng, quản lý môi trường, sản xuất công nghiệp, phòng chống thiên tai. Đồng thời thiết lập hệ thống quản lý an toàn năng lượng nguyên tố, ngăn ngừa thiệt hại do năng lượng mất kiểm soát.</li></ul><h3 id="_3-che-đo-cong-sinh-cua-chung-toc-cau-tao-co-khi" tabindex="-1">(3) Chế độ cộng sinh của Chủng tộc cấu tạo cơ khí <a class="header-anchor" href="#_3-che-đo-cong-sinh-cua-chung-toc-cau-tao-co-khi" aria-label="Permalink to &quot;(3) Chế độ cộng sinh của Chủng tộc cấu tạo cơ khí&quot;">​</a></h3><ul><li><strong>Chủng tộc Cơ khí</strong>: Phát huy khả năng tính toán và phòng thủ vật lý của Chủng tộc Cơ khí, đảm nhận vai trò cốt lõi trong các lĩnh vực như xây dựng hạ tầng, sản xuất công nghiệp, bảo vệ an ninh, thăm dò không gian sâu. Chủng tộc Cơ khí là nhà xây dựng quan trọng của phần cứng và hạ tầng Mỏ neo.</li><li><strong>Chủng tộc Số</strong>: Phát huy khả năng xử lý dữ liệu và thao tác thông tin của Chủng tộc Số, đảm nhận vai trò cốt lõi trong các lĩnh vực như xây dựng tin học hóa, phân tích dữ liệu, an ninh mạng, trí tuệ nhân tạo. Chủng tộc Số là người bảo trì quan trọng của công nghệ truyền thông liên giới và mạng lưới cộng sinh.</li><li><strong>Chủng tộc Tinh thể</strong>: Phát huy khả năng lưu trữ và chuyển đổi năng lượng của Chủng tộc Tinh thể, đảm nhận vai trò trong các lĩnh vực như dự trữ năng lượng, tiêu chuẩn hóa năng lượng, truyền tải năng lượng.</li></ul><h3 id="_4-che-đo-cong-sinh-cua-chung-toc-thong-tin-y-thuc" tabindex="-1">(4) Chế độ cộng sinh của Chủng tộc thông tin ý thức <a class="header-anchor" href="#_4-che-đo-cong-sinh-cua-chung-toc-thong-tin-y-thuc" aria-label="Permalink to &quot;(4) Chế độ cộng sinh của Chủng tộc thông tin ý thức&quot;">​</a></h3><ul><li><strong>Chủng tộc Mộng</strong>: Phát huy khả năng giao tiếp ý thức của Chủng tộc Mộng, đảm nhận vai trò trong các lĩnh vực như điều trị tâm lý, nghiên cứu ý thức, giao tiếp liên chủng tộc, trao đổi văn hóa. Thiết lập hệ thống quản lý không gian mộng, ngăn ngừa xâm nhập ý thức và xâm phạm quyền riêng tư.</li><li><strong>Chủng tộc Ảnh</strong>: Phát huy khả năng ẩn náu và lén lút của Chủng tộc Ảnh, đảm nhận vai trò trong các lĩnh vực như trinh sát an ninh, thu thập tình báo, nhiệm vụ đặc biệt. Đồng thời thiết lập chuẩn mực hành vi cho Chủng tộc Ảnh, ngăn ngừa khả năng vô hình bị sử dụng cho các hoạt động bất hợp pháp.</li><li><strong>Chủng tộc Niệm</strong>: Phát huy sức mạnh tinh thần và khả năng điều khiển tư tưởng của Chủng tộc Niệm, đảm nhận vai trò trong các lĩnh vực như nghiên cứu tiến hóa ý thức, điều trị tinh thần, hướng dẫn tu luyện cấp cao. Thiết lập chuẩn mực sử dụng sức mạnh tâm linh, ngăn ngừa kiểm soát tinh thần và thao túng ý thức.</li></ul><h3 id="_5-che-đo-cong-sinh-cua-chung-toc-đot-bien-hon-hop" tabindex="-1">(5) Chế độ cộng sinh của Chủng tộc đột biến hỗn hợp <a class="header-anchor" href="#_5-che-đo-cong-sinh-cua-chung-toc-đot-bien-hon-hop" aria-label="Permalink to &quot;(5) Chế độ cộng sinh của Chủng tộc đột biến hỗn hợp&quot;">​</a></h3><p>Chủng tộc đột biến hỗn hợp, do hình thái sự sống đặc biệt của mình, đòi hỏi chính sách cộng sinh tinh tế hơn:</p><ul><li>Thiết lập hệ thống đăng ký và chứng nhận danh tính cho Chủng tộc đột biến hỗn hợp, xác nhận địa vị pháp lý của nó.</li><li>Cung cấp các dịch vụ công cộng thích ứng như y tế, giáo dục, nhà ở cho các hình thái hỗn hợp khác nhau.</li><li>Phản đối sự phân biệt đối xử và loại trừ đối với Chủng tộc đột biến hỗn hợp, thúc đẩy sự chấp nhận của xã hội.</li><li>Đối với các hình thái hỗn hợp đặc biệt như Thể hồn kép, áp dụng 《58-Bộ chuẩn tắc đạo đức hồn kép》 để quản lý đặc biệt.</li></ul><h2 id="_4-bao-ve-van-hoa-cua-chung-toc-khac" tabindex="-1">4. Bảo vệ văn hóa của Chủng tộc Khác <a class="header-anchor" href="#_4-bao-ve-van-hoa-cua-chung-toc-khac" aria-label="Permalink to &quot;4. Bảo vệ văn hóa của Chủng tộc Khác&quot;">​</a></h2><p>Văn hóa của chủng tộc khác là một phần quan trọng của sự đa dạng văn hóa của tất cả các chủng tộc, và Nhà nước thực hiện các biện pháp sau để bảo vệ văn hóa của chủng tộc khác:</p><ol><li><strong>Điều tra dân số và ghi chép văn hóa</strong>: Thực hiện điều tra dân số và ghi chép có hệ thống về văn hóa của mỗi chủng tộc, xây dựng kho lưu trữ văn hóa của tất cả các chủng tộc, ngăn ngừa mất mát văn hóa.</li><li><strong>Bảo vệ ngôn ngữ và chữ viết</strong>: Bảo vệ ngôn ngữ và chữ viết của mỗi chủng tộc, hỗ trợ việc giảng dạy và sử dụng ngôn ngữ và chữ viết của chủng tộc khác, xây dựng hệ thống dịch vụ công cộng đa ngôn ngữ.</li><li><strong>Bảo vệ lễ hội truyền thống</strong>: Tôn trọng các lễ hội truyền thống và phong tục tập quán của mỗi chủng tộc, và việc sắp xếp ngày nghỉ công cộng xem xét các lễ hội quan trọng của mỗi chủng tộc.</li><li><strong>Hỗ trợ kế thừa văn hóa</strong>: Hỗ trợ đào tạo người kế thừa văn hóa và tổ chức các hoạt động văn hóa của mỗi chủng tộc, cung cấp hỗ trợ tài chính và không gian.</li><li><strong>Thúc đẩy trao đổi văn hóa</strong>: Thường xuyên tổ chức lễ hội văn hóa, triển lãm văn hóa và các hoạt động khác của tất cả các chủng tộc, thúc đẩy trao đổi và học hỏi lẫn nhau về văn hóa.</li><li><strong>Bảo vệ quyền sở hữu trí tuệ văn hóa</strong>: Bảo vệ quyền sở hữu trí tuệ của văn hóa truyền thống của mỗi chủng tộc, ngăn ngừa cướp bóc văn hóa và thương mại hóa không phù hợp.</li></ol><h2 id="_5-quan-ly-cac-van-đe-cua-chung-toc-khac" tabindex="-1">5. Quản lý các vấn đề của Chủng tộc Khác <a class="header-anchor" href="#_5-quan-ly-cac-van-đe-cua-chung-toc-khac" aria-label="Permalink to &quot;5. Quản lý các vấn đề của Chủng tộc Khác&quot;">​</a></h2><p>Nhà nước thành lập Bộ các vấn đề của tất cả các chủng tộc, chịu trách nhiệm đặc biệt về quản lý và điều phối các vấn đề của chủng tộc khác:</p><ul><li><strong>Hệ thống đại diện chủng tộc</strong>: Các cơ quan quản lý ở mọi cấp độ được trang bị đại diện của chủng tộc khác theo tỷ lệ, đảm bảo quyền lên tiếng của chủng tộc khác.</li><li><strong>Chính sách thích ứng chủng tộc</strong>: Xây dựng các chính sách dịch vụ công cộng khác biệt dựa trên đặc điểm sinh lý và nhu cầu văn hóa của các chủng tộc khác nhau.</li><li><strong>Hòa giải tranh chấp chủng tộc</strong>: Xây dựng cơ chế hòa giải tranh chấp chủng tộc, kịp thời giải quyết mâu thuẫn và xung đột giữa các chủng tộc.</li><li><strong>Hỗ trợ pháp lý cho chủng tộc khác</strong>: Cung cấp hỗ trợ pháp lý cho chủng tộc khác, đảm bảo họ được đối xử bình đẳng trong quá trình tư pháp.</li><li><strong>Hỗ trợ phát triển chủng tộc khác</strong>: Cung cấp hỗ trợ đặc biệt cho các chủng tộc tương đối chậm phát triển, giúp họ nâng cao mức độ văn minh và mức sống.</li></ul><h2 id="loi-ket" tabindex="-1">Lời kết <a class="header-anchor" href="#loi-ket" aria-label="Permalink to &quot;Lời kết&quot;">​</a></h2><p>Chủng tộc khác không phải là &quot;kẻ khác&quot; của Chủng tộc Người, mà là thành viên bình đẳng trong đại gia đình cộng sinh của tất cả các chủng tộc. Nền văn minh Cộng sinh Mỏ neo, thông qua việc xây dựng hệ thống phân loại đa chiều, áp dụng các chế độ cộng sinh khác biệt, bảo vệ văn hóa của chủng tộc khác, và cải thiện quản lý các vấn đề của chủng tộc khác, đảm bảo rằng mỗi chủng tộc khác đều có thể tìm thấy vị trí phù hợp trong hệ thống cộng sinh, phát huy ưu thế độc đáo của mình, và cùng với các chủng tộc khác tiến hóa và thịnh vượng.</p><h2 id="tai-lieu-lien-quan" tabindex="-1">Tài liệu liên quan <a class="header-anchor" href="#tai-lieu-lien-quan" aria-label="Permalink to &quot;Tài liệu liên quan&quot;">​</a></h2><ul><li>50-万族谱系总览 (Tổng quan về phả hệ tất cả các chủng tộc)</li><li>51-人族定位与特质 (Vị trí và Đặc điểm của Chủng tộc Người)</li><li>53-奇特生命识别标准 (Tiêu chuẩn nhận dạng sự sống kỳ lạ)</li><li>05-万族共进基本纲领 (Cương lĩnh cơ bản tiến bộ chung của tất cả các chủng tộc)</li></ul>',39)])])}const C=h(i,[["render",a]]);export{d as __pageData,C as default};
